INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'measure', 'n.', '/ˈmeʒə/', '措施;方法', 'We must take measures to protect people from disasters.', '我们必须采取措施保护人们免受灾害。', 'Disaster Survival', 1, 0, 'senior', 'wordlist', 'elective2', 'U4', 'take measures', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'resident', 'n.', '/ˈrezɪdənt/', '居民;住户', 'Local residents were moved to safety before the typhoon.', '当地居民在台风来临前被转移到了安全地带。', 'Disaster Survival', 2, 0, 'senior', 'wordlist', 'elective2', 'U4', 'local residents', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'port', 'n.', '/pɔːt/', '港口;避风港', 'Fishing boats hurried back to port before the storm.', '渔船在风暴来临前匆匆驶回港口。', 'Disaster Survival', 3, 0, 'senior', 'wordlist', 'elective2', 'U4', 'return to port', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'strand', 'v.', '/strænd/', '使滞留;使搁浅', 'Many drivers were stranded as the roads slowly flooded.', '随着道路渐渐被淹,许多司机被困在了路上。', 'Disaster Survival', 4, 0, 'senior', 'wordlist', 'elective2', 'U4', 'be stranded', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ease', 'v.', '/iːz/', '缓缓移动;减轻', 'He eased the car to a stop when the ground began to shake.', '地面开始晃动时,他缓缓把车停了下来。', 'Disaster Survival', 5, 0, 'senior', 'wordlist', 'elective2', 'U4', 'ease off', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'sturdy', 'adj.', '/ˈstɜːdi/', '结实的;坚固的', 'Put on sturdy shoes before you walk through the ruins.', '在走过废墟前先穿上结实的鞋子。', 'Disaster Survival', 6, 0, 'senior', 'wordlist', 'elective2', 'U4', 'sturdy shoes', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'pipe', 'n.', '/paɪp/', '管子;管道', 'Check for broken pipes before you turn on the gas.', '打开燃气前先检查有没有破损的管道。', 'Disaster Survival', 7, 0, 'senior', 'wordlist', 'elective2', 'U4', 'broken pipes', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'shift', 'v.', '/ʃɪft/', '转移;挪动', 'Heavy objects may shift and fall during a quake.', '地震时重物可能会挪动并掉落。', 'Disaster Survival', 8, 0, 'senior', 'wordlist', 'elective2', 'U4', 'shift position', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'plaster', 'n.', '/ˈplɑːstə/', '灰泥', 'Lumps of plaster fell from the ceiling and hit his head.', '一块块灰泥从天花板上掉下来砸在他头上。', 'Disaster Survival', 9, 0, 'senior', 'wordlist', 'elective2', 'U4', 'lumps of plaster', '美音 /ˈplæstər/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'shatter', 'v.', '/ˈʃætə/', '(使)破碎;粉碎', 'The windows shattered as the whole building shook.', '整栋楼晃动时,窗户都碎裂了。', 'Disaster Survival', 10, 0, 'senior', 'wordlist', 'elective2', 'U4', 'windows shatter', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'throat', 'n.', '/θrəʊt/', '咽喉;喉咙', 'Dust filled his throat and he could not even scream.', '灰尘塞满了他的喉咙,他连喊都喊不出来。', 'Disaster Survival', 11, 0, 'senior', 'wordlist', 'elective2', 'U4', 'dust in the throat', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'coat', 'v.', '/kəʊt/', '覆盖;涂上一层', 'His throat was coated with thick grey dust.', '他的喉咙被一层厚厚的灰尘覆盖着。', 'Disaster Survival', 12, 0, 'senior', 'wordlist', 'elective2', 'U4', 'be coated with', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'burst', 'v.', '/bɜːst/', '(使)爆裂;胀开', 'The ceiling burst open right above his head.', '天花板就在他头顶上方猛然裂开。', 'Disaster Survival', 13, 0, 'senior', 'wordlist', 'elective2', 'U4', 'burst open', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'leap', 'v.', '/liːp/', '猛冲;跳跃', 'They leaped towards the door as the bricks fell.', '砖块掉落时,他们猛地冲向门口。', 'Disaster Survival', 14, 0, 'senior', 'wordlist', 'elective2', 'U4', 'leap towards', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'pour', 'v.', '/pɔː/', '倾泻;喷涌', 'Bricks poured down through the open doorway.', '砖块从敞开的门口倾泻而下。', 'Disaster Survival', 15, 0, 'senior', 'wordlist', 'elective2', 'U4', 'pour down', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'spill', 'v.', '/spɪl/', '涌出;溢出', 'Stones and broken glass spilled into the street.', '石块和碎玻璃涌进了街道。', 'Disaster Survival', 16, 0, 'senior', 'wordlist', 'elective2', 'U4', 'spill into', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'bury', 'v.', '/ˈberi/', '掩埋;埋葬', 'They would have been buried if they had been a little slower.', '如果他们再慢一点,就会被埋住了。', 'Disaster Survival', 17, 0, 'senior', 'wordlist', 'elective2', 'U4', 'be buried', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'furious', 'adj.', '/ˈfjʊəriəs/', '猛烈的;狂怒的', 'The earthquake tore through the city like a furious giant.', '地震像一个狂怒的巨人般撕裂了城市。', 'Disaster Survival', 18, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a furious giant', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'unsteady', 'adj.', '/ʌnˈstedi/', '摇晃的;不稳的', 'Some unsteady houses collapsed soon after the shaking.', '一些摇摇欲坠的房子在震动后不久就倒塌了。', 'Disaster Survival', 19, 0, 'senior', 'wordlist', 'elective2', 'U4', 'unsteady houses', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'stretch', 'v.', '/stretʃ/', '横躺;伸展', 'Some people lay stretched across the sidewalk, not moving.', '一些人横躺在人行道上,一动不动。', 'Disaster Survival', 20, 0, 'senior', 'wordlist', 'elective2', 'U4', 'stretch across', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ash', 'n.', '/æʃ/', '灰;灰烬', 'Their hands were black with ash after the fire.', '火灾过后,他们的手被灰烬染得黑黑的。', 'Disaster Survival', 21, 0, 'senior', 'wordlist', 'elective2', 'U4', 'black with ash', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'raw', 'adj.', '/rɔː/', '红肿破损的;生的', 'His fingers were scratched raw in several spots.', '他的手指好几处都被擦得红肿破皮。', 'Disaster Survival', 22, 0, 'senior', 'wordlist', 'elective2', 'U4', 'scratched raw', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'spot', 'n.', '/spɒt/', '地点;斑点', 'Keep your emergency kit in an easy-to-reach spot.', '把应急包放在容易拿到的地方。', 'Disaster Survival', 23, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a safe spot', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'strike', 'v.', '/straɪk/', '侵袭;爆发;击打', 'Earthquakes can strike without any warning at all.', '地震可能毫无预警地突然发生。', 'Disaster Survival', 24, 0, 'senior', 'wordlist', 'elective2', 'U4', 'strike without warning', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'typhoon', 'n.', '/taɪˈfuːn/', '台风', 'A strong typhoon struck the southern coast last night.', '昨晚一场强台风袭击了南部海岸。', 'Disaster Survival', 25, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a strong typhoon', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'gush', 'v.', '/ɡʌʃ/', '喷涌;涌出', 'Flood water gushed through the broken wall.', '洪水从破裂的墙体喷涌而入。', 'Disaster Survival', 26, 0, 'senior', 'wordlist', 'elective2', 'U4', 'gushing water', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'avalanche', 'n.', '/ˈævəlɑːnʃ/', '雪崩;山崩', 'An avalanche can bury a whole village under the snow.', '一场雪崩能把整个村庄埋在雪下。', 'Disaster Survival', 27, 0, 'senior', 'wordlist', 'elective2', 'U4', 'an avalanche hits', '美音 /ˈævəlæntʃ/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'raging', 'adj.', '/ˈreɪdʒɪŋ/', '猛烈的;狂暴的', 'The raging flames of the wildfire spread very quickly.', '野火的熊熊烈焰蔓延得非常快。', 'Disaster Survival', 28, 0, 'senior', 'wordlist', 'elective2', 'U4', 'raging flames', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'flame', 'n.', '/fleɪm/', '火焰;火舌', 'Put out all flames the moment an earthquake starts.', '地震一开始就要熄灭所有的火焰。', 'Disaster Survival', 29, 0, 'senior', 'wordlist', 'elective2', 'U4', 'put out the flames', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'emergency', 'n.', '/ɪˈmɜːdʒənsi/', '紧急情况;突发事件', 'Keep an emergency kit ready in case of a disaster.', '备好应急包,以防发生灾难。', 'Disaster Survival', 30, 0, 'senior', 'wordlist', 'elective2', 'U4', 'in an emergency', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'secure', 'adj.', '/sɪˈkjʊə/', '牢固的;安心的', 'Hide in a secure basement during a strong typhoon.', '强台风期间要躲进牢固的地下室。', 'Disaster Survival', 31, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a secure basement', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'basement', 'n.', '/ˈbeɪsmənt/', '地下室;地库', 'A basement with no windows is a safe place in a storm.', '没有窗户的地下室是风暴中安全的地方。', 'Disaster Survival', 32, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a safe basement', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'solid', 'adj.', '/ˈsɒlɪd/', '结实的;坚固的;固体的', 'Get under a solid piece of furniture to protect yourself.', '躲到结实的家具下面来保护自己。', 'Disaster Survival', 33, 0, 'senior', 'wordlist', 'elective2', 'U4', 'solid furniture', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'furniture', 'n.', '/ˈfɜːnɪtʃə/', '家具', 'Fix tall furniture to the wall so it cannot fall on you.', '把高大的家具固定在墙上,免得它砸到你。', 'Disaster Survival', 34, 0, 'senior', 'wordlist', 'elective2', 'U4', 'heavy furniture', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'battery', 'n.', '/ˈbætəri/', '电池', 'A battery-powered radio still works when the power is off.', '停电时,用电池的收音机依然能工作。', 'Disaster Survival', 35, 0, 'senior', 'wordlist', 'elective2', 'U4', 'battery-powered', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'evacuation', 'n.', '/ɪˌvækjuˈeɪʃn/', '疏散;撤离', 'Follow the evacuation order and leave for higher ground.', '听从撤离命令,前往地势更高的地方。', 'Disaster Survival', 36, 0, 'senior', 'wordlist', 'elective2', 'U4', 'an evacuation order', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'intense', 'adj.', '/ɪnˈtens/', '强烈的;剧烈的', 'Floods are often caused by intense rain lasting for days.', '洪水常由连日的强降雨引起。', 'Disaster Survival', 37, 0, 'senior', 'wordlist', 'elective2', 'U4', 'intense rainfall', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'warning', 'n.', '/ˈwɔːnɪŋ/', '警告;警示', 'When you hear the warning, move to a safer place at once.', '听到警报时,立刻转移到更安全的地方。', 'Disaster Survival', 38, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a flood warning', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'waterproof', 'adj.', '/ˈwɔːtəpruːf/', '防水的;不透水的', 'Keep your papers in a waterproof container during a flood.', '洪水期间把证件放在防水容器里。', 'Disaster Survival', 39, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a waterproof container', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'container', 'n.', '/kənˈteɪnə/', '容器', 'Store clean water in a sealed container before the storm.', '风暴来临前把干净水储存在密封容器里。', 'Disaster Survival', 40, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a sealed container', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'slope', 'n.', '/sləʊp/', '斜坡;坡地', 'Move to the side of the slope when an avalanche starts.', '雪崩开始时,移向斜坡的边缘。', 'Disaster Survival', 41, 0, 'senior', 'wordlist', 'elective2', 'U4', 'the side of the slope', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'equipment', 'n.', '/ɪˈkwɪpmənt/', '设备;器材', 'Drop any heavy equipment so that you can move faster.', '扔掉沉重的器材,这样你能跑得更快。', 'Disaster Survival', 42, 0, 'senior', 'wordlist', 'elective2', 'U4', 'heavy equipment', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ensure', 'v.', '/ɪnˈʃʊə/', '确保;保证', 'Cover your mouth with a wet cloth to ensure you can breathe.', '用湿布捂住口鼻,确保你还能呼吸。', 'Disaster Survival', 43, 0, 'senior', 'wordlist', 'elective2', 'U4', 'ensure safety', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'pond', 'n.', '/pɒnd/', '池塘;人工池', 'In a wildfire, get close to a pond or river if you can.', '野火中如果可能,尽量靠近池塘或河流。', 'Disaster Survival', 44, 0, 'senior', 'wordlist', 'elective2', 'U4', 'near a pond', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'spark', 'v.', '/spɑːk/', '冒火花;引发', 'Move to ground that has burned out and is less likely to spark again.', '移到已经烧尽、不太会再起火的地面上。', 'Disaster Survival', 45, 0, 'senior', 'wordlist', 'elective2', 'U4', 'spark again', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'blanket', 'n.', '/ˈblæŋkɪt/', '毯子;毛毯', 'Cover yourself with a wet blanket until the fire passes.', '用湿毯子盖住自己,直到火势过去。', 'Disaster Survival', 46, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a wet blanket', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'firefighter', 'n.', '/ˈfaɪəfaɪtə/', '消防队员', 'Leave the door unlocked so firefighters can reach you.', '让门开着,这样消防队员能找到你。', 'Disaster Survival', 47, 0, 'senior', 'wordlist', 'elective2', 'U4', 'call the firefighters', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'kit', 'n.', '/kɪt/', '成套工具;工具包', 'A basic survival kit should hold food, water and a torch.', '一个基本的求生包应该装有食物、水和手电筒。', 'Disaster Survival', 48, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a survival kit', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'damp', 'adj.', '/dæmp/', '潮湿的;微湿的', 'Keep a few damp towels in your emergency bag.', '在应急包里放几条湿毛巾。', 'Disaster Survival', 49, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a damp towel', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'backup', 'n.', '/ˈbækʌp/', '备用;后援', 'Pack a phone with backup batteries for emergencies.', '带上一部配有备用电池的手机以备紧急之需。', 'Disaster Survival', 50, 0, 'senior', 'wordlist', 'elective2', 'U4', 'backup batteries', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u4.01', '①被动式动名词 being done(动作的承受者)', 'A2', 11, '上外版选择性必修第二册 U4 — 当 -ing 形式的逻辑主语是动作的承受者(被…)时,介词后或作主语/宾语用被动式动名词 being done。', 1, 'elective2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u4.02', '②完成式动名词 having done(先于主句的动作)', 'A2', 11, '上外版选择性必修第二册 U4 — 当 -ing 表示的动作主动发生、且明显早于主句动作完成时,用完成式 having done。', 2, 'elective2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u4.03', '③否定式 not doing 与带逻辑主语的复合动名词 sb doing', 'A2', 11, '上外版选择性必修第二册 U4 — 在 -ing 前加 not 构成否定式;-ing 前可带自己的逻辑主语(代词/名词)构成复合结构。', 3, 'elective2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'The little boy was terrified of ____ under the broken wall.', 'being buried', 'burying', 'having buried', 'to bury', 'A', '男孩是被埋的承受者,介词 of 后用被动式动名词 being buried;burying 表主动埋别人,与句意不符。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'No one enjoys ____ alone in the dark during a long power cut.', 'leaving', 'being left', 'having left', 'to leave', 'B', '人是被独自留下的对象,用被动式 being left;leaving 表主动离开,意思相反。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'The trapped miners had little hope of ____ before their air ran out.', 'rescuing', 'having rescued', 'being rescued', 'to rescue', 'C', '矿工是被营救的对象,of 后用被动式 being rescued。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'These old houses are in real danger of ____ down in the next quake.', 'knocking', 'having knocked', 'to knock', 'being knocked', 'D', '房子是被震倒的承受者,用被动式 being knocked down。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'The villagers were afraid of ____ by the fast-rising flood water.', 'being trapped', 'trapping', 'having trapped', 'to trap', 'A', '村民是被困的对象,of 后用被动式 being trapped。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'The injured man was carried out without ____ by anyone in the crowd.', 'noticing', 'being noticed', 'having noticed', 'to notice', 'B', '他是被注意的对象,without 后用被动式 being noticed。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'She hated ____ in the crowded shelter with no news for hours.', 'keeping', 'having kept', 'being kept', 'to keep', 'C', '她是被滞留的对象,用被动式 being kept;keeping 表主动保留某物,与句意不符。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'The villagers still remember ____ of the coming typhoon by the radio.', 'warning', 'having warned', 'to warn', 'being warned', 'D', '村民是被警告的对象,用被动式 being warned。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'After ____ from the rubble at last, the child cried with joy.', 'being pulled', 'pulling', 'having pulled', 'to pull', 'A', '孩子是被拉出的对象,after 后用被动式 being pulled。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'The frightened dog was scared of ____ behind in the flooded house.', 'leaving', 'being left', 'having left', 'to leave', 'B', '狗是被留下的对象,of 后用被动式 being left。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'A good shelter saves people from ____ by falling stones.', 'hitting', 'having hit', 'being hit', 'to hit', 'C', '人是被砸的对象,save sb from 后用被动式 being hit。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'The old bridge was at risk of ____ away by the powerful flood.', 'washing', 'having washed', 'to wash', 'being washed', 'D', '桥是被冲走的对象,of 后用被动式 being washed away。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'Nobody likes ____ woken by a loud alarm in the middle of the night.', 'being woken', 'waking', 'having woken', 'to wake', 'A', '人是被吵醒的对象,用被动式 being woken。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'The climbers were in danger of ____ by a sudden avalanche.', 'burying', 'being buried', 'having buried', 'to bury', 'B', '登山者是被掩埋的对象,of 后用被动式 being buried。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'He escaped from the building without ____ by the falling bricks.', 'striking', 'having struck', 'being struck', 'to strike', 'C', '他是被砸的对象,without 后用被动式 being struck。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'The low town could not avoid ____ by the huge waves of the storm.', 'flooding', 'having flooded', 'to flood', 'being flooded', 'D', '城镇是被淹的对象,avoid 后用被动式 being flooded。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'Important papers should be kept dry to stop them from ____ in the flood.', 'being ruined', 'ruining', 'having ruined', 'to ruin', 'A', '文件是被毁坏的对象,stop...from 后用被动式 being ruined。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'The little cat hid under the bed to keep from ____ during the quake.', 'seeing', 'being seen', 'having seen', 'to see', 'B', '猫是被看见的对象,keep from 后用被动式 being seen。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'Several survivors spoke of ____ for hours before any help arrived.', 'trapping', 'having trapped', 'being trapped', 'to trap', 'C', '幸存者是被困的对象,of 后用被动式 being trapped。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.01'), 'The little girl was proud of ____ to safety by the brave firefighter.', 'carrying', 'having carried', 'to carry', 'being carried', 'D', '女孩是被抱到安全处的对象,of 后用被动式 being carried。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ everything they owned in the flood, the family had to start again.', 'Having lost', 'Being lost', 'Having been lost', 'To lose', 'A', '他们主动失去财物且早于主句,用完成式 Having lost;被动式与句意不符。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ the residents in good time, the police moved on to the next village.', 'Being warned', 'Having warned', 'Having been warned', 'To warn', 'B', '警察先警告了居民再前往,主动且在先,用 Having warned。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), 'The rescuer was proud of ____ ten people the day before.', 'being saved', 'having been saved', 'having saved', 'to save', 'C', '救援者主动救人且发生在''前一天'',of 后用完成式 having saved。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ through several earthquakes, the old man stayed calm this time.', 'Being lived', 'Having been lived', 'To live', 'Having lived', 'D', '老人经历过多次地震在先,用主动完成式 Having lived through。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ their homes to the fire, the villagers were still grateful to be alive.', 'Having lost', 'Being lost', 'Having been lost', 'To lose', 'A', '村民先失去家园,主动且在先,用 Having lost。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), 'She thanked the soldiers for ____ her family well before the dam broke.', 'being warned', 'having warned', 'having been warned', 'to warn', 'B', '士兵主动警告且在大坝决堤''之前'',for 后用完成式 having warned。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ a strong shelter earlier, they felt safe when the typhoon came.', 'Being built', 'Having been built', 'Having built', 'To build', 'C', '他们更早就建好了避难所,主动且在先,用 Having built。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ everyone out of the building, the firefighters finally took a rest.', 'Being led', 'Having been led', 'To lead', 'Having led', 'D', '消防员先把人带出再休息,主动在先,用 Having led。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), 'The captain was praised for ____ all the passengers before the ship sank.', 'having saved', 'being saved', 'having been saved', 'to save', 'A', '船长主动救人且在沉船''之前'',for 后用完成式 having saved。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ the danger before others, he was able to warn the whole street.', 'Being seen', 'Having seen', 'Having been seen', 'To see', 'B', '他先看出危险才去示警,主动在先,用 Having seen。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ many lives in past floods, the river was finally controlled by a new dam.', 'Being taken', 'Having been taken', 'Having taken', 'To take', 'C', '河流过去夺去许多生命在先,主动用 Having taken。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), 'After ____ for help for hours, the trapped workers heard the rescue team.', 'being shouted', 'having been shouted', 'to shout', 'having shouted', 'D', '他们主动呼救数小时在先,after 后用主动完成式 having shouted;shout 不及物,无被动。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ all our water on the first day, we had nothing left to drink later.', 'Having used', 'Being used', 'Having been used', 'To use', 'A', '我们先用光了水,主动在先,用 Having used。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), 'He felt sorry for ____ the warning, which had cost the family their home.', 'being ignored', 'having ignored', 'having been ignored', 'to ignore', 'B', '他主动忽视了警告在先,for 后用完成式 having ignored。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ a kit ready well in advance, they faced the typhoon quite calmly.', 'Being prepared', 'Having been prepared', 'Having prepared', 'To prepare', 'C', '他们事先备好了求生包,主动在先,用 Having prepared。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), 'The town was proud of ____ thousands of people during the great flood.', 'being sheltered', 'having been sheltered', 'to shelter', 'having sheltered', 'D', '小镇主动收容了数千人,of 后用完成式 having sheltered。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ from the avalanche just in time, the skiers hugged each other.', 'Having escaped', 'Being escaped', 'Having been escaped', 'To escape', 'A', '滑雪者先逃出雪崩再相拥,主动在先;escape 不及物,无被动,用 Having escaped。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), 'She remembered ____ the gas before leaving, so she felt relieved.', 'being turned off', 'having turned off', 'having been turned off', 'to turn off', 'B', '她主动关了燃气且在离开''之前'',用完成式 having turned off。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), '____ the children to safety first, the teacher went back for the others.', 'Being taken', 'Having been taken', 'Having taken', 'To take', 'C', '老师先把孩子带到安全处再返回,主动在先,用 Having taken。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.02'), 'The volunteers were thanked for ____ so much food before the roads closed.', 'being brought', 'having been brought', 'to bring', 'having brought', 'D', '志愿者主动送来食物且在封路''之前'',for 后用完成式 having brought。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), '____ what was happening, the children kept playing in the street.', 'Not knowing', 'Knowing', 'Not known', 'Not having known', 'A', '与主句同时发生、表否定原因,用否定式 Not knowing。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), '____ where to hide, the tourists ran in all directions during the quake.', 'Knowing', 'Not knowing', 'Not known', 'Not having known', 'B', '不知道往哪躲(同时、否定原因),用 Not knowing。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'The driver apologised for ____ the warning signs on the flooded road.', 'noticing', 'not noticed', 'not noticing', 'not to notice', 'C', 'for 后接否定式动名词 not noticing,表''没注意到''。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'She blamed herself for ____ the family earlier about the storm.', 'warning', 'not warned', 'not to warn', 'not warning', 'D', 'for 后用否定式动名词 not warning,表''没早点提醒''。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), '____ the evacuation order, some people stayed and put themselves in danger.', 'Not following', 'Following', 'Not followed', 'Not to follow', 'A', '没听从撤离令(否定原因),用否定式 Not following。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'He felt guilty about ____ enough water before the shops all closed.', 'buying', 'not buying', 'not bought', 'not to buy', 'B', 'about 后用否定式动名词 not buying,表''没买够''。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), '____ for two days, the trapped hikers grew weak and cold.', 'Not eating', 'Not eaten', 'Not having eaten', 'Being not eaten', 'C', '''两天没吃东西''早于主句且需完成意味,用否定完成式 Not having eaten。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'The town suffered badly for ____ ready for such a strong typhoon.', 'being', 'not been', 'not to be', 'not being', 'D', 'for 后用否定式动名词 not being ready,表''没做好准备''。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), '____ the gas before he left the house, the man caused a small fire.', 'Not turning off', 'Turning off', 'Not turned off', 'Not to turn off', 'A', '''没关燃气''是起火原因,用否定式 Not turning off。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'I really regret ____ to the weather warning on the radio that night.', 'listening', 'not listening', 'not listened', 'not to listen', 'B', 'regret 后用否定式动名词 not listening,表''后悔没听''。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'There is no point in us ____ in such a dangerous area any longer.', 'stayed', 'to stay', 'staying', 'being stayed', 'C', '介词 in 后接动名词,逻辑主语 us + staying。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'Nothing could stop the river ____ its banks during the heavy storm.', 'broken', 'to break', 'being broken', 'breaking', 'D', 'stop sth doing 结构,逻辑主语 the river + breaking。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'We were grateful for the soldiers ____ us food and clean water.', 'bringing', 'brought', 'to bring', 'being brought', 'A', '介词 for 后接动名词,逻辑主语 the soldiers + bringing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'I don''t mind the neighbours ____ in our shelter for the night.', 'stayed', 'staying', 'to stay', 'being stayed', 'B', 'mind 后接动名词,逻辑主语 the neighbours + staying。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'The loud alarm prevented the family from ____ asleep in the smoke.', 'stayed', 'to stay', 'staying', 'being stayed', 'C', 'prevent...from 后接动名词,逻辑主语 the family + staying。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'Everyone was surprised at the firefighters ____ the fire so quickly.', 'put out', 'to put out', 'being put out', 'putting out', 'D', 'at 后接动名词,逻辑主语 the firefighters + putting out。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'There is little chance of the storm ____ before midnight tonight.', 'passing', 'passed', 'to pass', 'being passed', 'A', 'of 后接动名词,逻辑主语 the storm + passing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'We could not imagine the water ____ so fast inside the house.', 'risen', 'rising', 'to rise', 'being risen', 'B', 'imagine 后接动名词,逻辑主语 the water + rising;rise 不及物,无被动。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'It is no use the children ____ when the lift has already stopped.', 'shouted', 'to shout', 'shouting', 'being shouted', 'C', 'It is no use doing 结构,逻辑主语 the children + shouting。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U4' AND code='se2u4.03'), 'The whole rescue depended on the helicopter ____ before dark.', 'arrived', 'to arrive', 'being arrived', 'arriving', 'D', 'depend on 后接动名词,逻辑主语 the helicopter + arriving;arrive 不及物,无被动。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Surviving an Earthquake', 'At twelve minutes past five in the morning, a loud roar woke the whole town. The ground shook so hard that people could not stand. Mirrors fell from the walls and broke into pieces, lumps of plaster dropped from the ceilings, and windows shattered all around. Many people wanted to run, but the shaking was too strong, and dust filled their throats so that they could hardly breathe. When the earth finally grew still, the silence felt almost as frightening as the noise had been. The streets were covered with bricks, stones and broken glass. Some weak houses had fallen down, while others looked as if a single push would send them crashing. Yet within a few days, the people began to talk about rebuilding. They set up tents, shared food and water, and helped one another search for those who were still missing. Their hands were cut and black with ash, but together they still looked strong. The city was gone, they said, but its spirit was very much alive.', '记叙·一场地震中的求生', 171, '[{"q":"What woke the people of the town that morning?","answer":"A","options":["A loud roar as the ground began to shake.","A heavy rainstorm outside.","The ringing of the school bells.","A fire in the busy market."],"explanation":"原文 ''a loud roar woke the whole town'' 与随后地面摇晃的转述。"},{"q":"Why could many people not run away at first?","answer":"B","options":["Because all the doors were locked.","The violent shaking and the dust in their throats stopped them.","Because they were still fast asleep.","Because the streets were far too crowded."],"explanation":"原文 ''摇晃太强、灰尘塞满喉咙'' 的转述,非照抄。"},{"q":"What did the people decide to do within a few days?","answer":"A","options":["Begin to rebuild their ruined town together.","Leave the area for ever.","Blame one another for the damage.","Wait quietly for outside help."],"explanation":"原文 ''began to talk about rebuilding'' 的转述。"}]'::jsonb, '[{"word":"plaster","cn":"灰泥"},{"word":"shatter","cn":"破碎"},{"word":"ash","cn":"灰烬"}]'::jsonb, 2, 'elective2', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'When a Typhoon Comes', 'Typhoons are violent tropical storms that bring powerful winds and heavy rain. They form over warm seas and often strike coastal areas without much warning. In southern China, people have learned to take them seriously. Before a typhoon arrives, fishing boats hurry back to port, and residents living near the water are moved to safer places. The safest spot to hide is a strong room with no windows, such as a basement or an inner bathroom. It is also wise to stay under solid furniture in case the roof gives way. A battery-powered radio is one of the most useful things to keep, because the power often goes out during a storm. Through it you can hear evacuation orders and learn when the danger has finally passed. After the storm, streets may be flooded and roads blocked, so it is best to stay indoors until the local government says it is safe to go out. A little planning can turn a terrible night into one your family will simply remember, not regret.', '说明·台风的防护', 172, '[{"q":"Where do typhoons usually form?","answer":"B","options":["On high mountains.","Over warm seas.","In dry deserts.","Deep inside cities."],"explanation":"原文 ''form over warm seas'' 的转述。"},{"q":"Why is a battery-powered radio so useful in a typhoon?","answer":"C","options":["It can stop the strong wind.","It dries wet clothes quickly.","It still works when the electricity is cut off.","It cooks food without a fire."],"explanation":"原文 ''the power often goes out'' 的转述。"},{"q":"What should people do right after the storm?","answer":"D","options":["Rush outside to see the damage.","Drive through the flooded roads at once.","Open all the windows immediately.","Stay inside until officials say it is safe."],"explanation":"原文 ''stay indoors until the local government says it is safe'' 的转述。"}]'::jsonb, '[{"word":"typhoon","cn":"台风"},{"word":"port","cn":"港口"},{"word":"evacuation","cn":"撤离"}]'::jsonb, 2, 'elective2', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Staying Safe in a Flood', 'Floods happen more often than any other natural disaster, and they can change the land in a single night. Most floods are caused by intense rain that lasts for days, though a broken dam or a high sea tide can also be to blame. The water rises slowly at first, then faster and faster, until quiet streets turn into rushing rivers. The most important rule is simple: never try to be a hero by staying in your house. As soon as you hear a flood warning, leave for higher ground. Take only what you really need, and keep your money and important papers inside a waterproof bag. Never try to walk or drive through moving water, because even a small amount can sweep a person or a car away in seconds. If you do become trapped, climb to the highest floor and call for help. Clean water may be hard to find afterwards, so it is wise to store some in a sealed container before the flood ever reaches you.', '说明·洪水中的自救', 170, '[{"q":"What causes most floods, according to the text?","answer":"A","options":["Days of heavy, intense rain.","A sudden strong earthquake.","Cold ocean winds.","A very long dry season."],"explanation":"原文 ''intense rain that lasts for days'' 的转述。"},{"q":"What is the most important rule during a flood?","answer":"B","options":["Stay in the house to guard it.","Leave for higher ground instead of staying home.","Wait until the water reaches the roof.","Swim across the moving water."],"explanation":"原文 ''never try to be a hero by staying in your house... leave for higher ground'' 的转述。"},{"q":"Why should people avoid moving water?","answer":"C","options":["Because it is always dirty.","Because it is too cold to touch.","Even shallow, fast water is strong enough to knock you down.","Because it makes loud noises."],"explanation":"原文 ''even a small amount can sweep a person or a car away'' 的转述。"}]'::jsonb, '[{"word":"intense","cn":"强烈的"},{"word":"warning","cn":"警告"},{"word":"waterproof","cn":"防水的"}]'::jsonb, 2, 'elective2', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Caught in an Avalanche', 'An avalanche is a huge mass of snow and ice that suddenly slides down a mountain. It can happen while skiers are enjoying a beautiful slope, and it moves so fast that there is very little time to react. If you ever see one start, try to move to the side of the slope at once, because the deepest snow rushes down through the middle. Dropping any heavy equipment will help you move more quickly and stay nearer the surface. If the snow buries you, the most important thing is to make a small space in front of your face so that you can keep breathing. Do not waste your strength by shouting or digging without a plan, since this only uses up the air and energy you badly need. Instead, stay calm and wait. When you hear the rescue team coming close, call out to them. Many people who keep their heads have been found alive hours after the snow finally stopped moving.', '说明·雪崩中的逃生', 164, '[{"q":"What should you do first when an avalanche begins?","answer":"D","options":["Ski straight down the middle.","Lie down and cover your head.","Climb higher up the mountain.","Get out of the centre and head to the slope''s edge."],"explanation":"原文 ''move to the side of the slope... the deepest snow rushes down through the middle'' 的转述。"},{"q":"Why should you drop heavy equipment?","answer":"A","options":["So you can move faster and stay near the surface.","To make the snow stop sliding.","To keep your hands warm.","To signal a helicopter above."],"explanation":"原文 ''help you move more quickly and stay nearer the surface'' 的转述。"},{"q":"Why is it unwise to shout and dig wildly under the snow?","answer":"B","options":["It makes the snow melt faster.","It quickly burns the strength a trapped person must save.","It frightens the rescue team away.","It is against the mountain rules."],"explanation":"原文 ''uses up the air and energy you badly need'' 的转述。"}]'::jsonb, '[{"word":"avalanche","cn":"雪崩"},{"word":"slope","cn":"斜坡"},{"word":"equipment","cn":"器材"}]'::jsonb, 2, 'elective2', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Surviving a Wildfire', 'Wildfires can start in nature or be caused by people, and they spread at an amazing speed, destroying almost everything in their path. If you are ever caught in one, remember that the smoke is often more dangerous than the flames, so cover your nose and mouth with a wet cloth to help you breathe. Try to keep the wind behind the fire and in front of you, and move towards a pond, a river or any large open water. If there is no water nearby, head for ground that has already burned, because it has very little left to catch fire again. Stay as low as you can and cover yourself with wet clothing, a blanket or even soil until the fire passes by. If you have no other choice, go inside a building, shut every door and window, but leave the doors unlocked so that firefighters can reach you later. Acting calmly and quickly always gives you the best chance of staying alive.', '说明·野火中的求生', 165, '[{"q":"What is often more dangerous than the flames in a wildfire?","answer":"C","options":["The noise.","The light.","The smoke.","The heat of the sun."],"explanation":"原文 ''the smoke is often more dangerous than the flames'' 的转述。"},{"q":"Why should you move to ground that has already burned?","answer":"D","options":["It is always much cooler.","It is closer to the main road.","It is easier to dig into.","It has little fuel left to burn again."],"explanation":"原文 ''little left to catch fire again'' 的转述。"},{"q":"Why leave the doors of the building unlocked?","answer":"A","options":["So that firefighters are able to reach you.","To let the smoke escape outside.","To keep the building cool.","To save electricity at night."],"explanation":"原文 ''leave the doors unlocked so that firefighters can reach you'' 的转述。"}]'::jsonb, '[{"word":"raging","cn":"猛烈的"},{"word":"pond","cn":"池塘"},{"word":"firefighter","cn":"消防员"}]'::jsonb, 2, 'elective2', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Team That Brings Hope', 'When a major disaster strikes, trained rescue teams are often the difference between life and death. China''s international search and rescue team was set up in 2001, and in only ten years it grew from a few hundred members to around four hundred and fifty. The team has carried out many missions, both at home and abroad. After a powerful earthquake hit Nepal in 2015, for example, Chinese experts flew there to help dig survivors out of the ruins. Such teams remind us that every family should also be ready at home. A basic survival kit can keep a family safe for the first few days, when help may not yet have arrived. It should hold enough food and clean water for at least three days, a torch with spare batteries, a first-aid box, a whistle and a dust mask. Some damp towels and a phone with backup batteries are useful too. Once your kit is ready, you are far better prepared for whatever may come your way.', '说明·救援队与求生包', 168, '[{"q":"When was China''s search and rescue team set up?","answer":"B","options":["In 2015.","In 2001.","In 1990.","In 2020."],"explanation":"原文 ''set up in 2001''。"},{"q":"What did the team do after the 2015 Nepal earthquake?","answer":"C","options":["Sent only money to the country.","Built a new airport there.","Sent experts to help free survivors from the ruins.","Trained the local farmers."],"explanation":"原文 ''flew there to help dig survivors out of the ruins'' 的转述。"},{"q":"Why should a family keep a survival kit?","answer":"D","options":["To save money on shopping.","To use it on family holidays.","To give it away as a gift.","To stay safe in the first days before help arrives."],"explanation":"原文 ''keep a family safe for the first few days, when help may not yet have arrived'' 的转述。"}]'::jsonb, '[{"word":"kit","cn":"成套工具"},{"word":"backup","cn":"备用"},{"word":"damp","cn":"潮湿的"}]'::jsonb, 2, 'elective2', 'U4', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'A Family Emergency Plan', 'Disasters can strike at any time, so every family should have a (1)____ ready in advance. Sit down together and choose a safe (2)____ where everyone will meet if you are separated. Next, learn the quickest (3)____ out of your home and out of your neighbourhood. It is also important to (4)____ a basic kit with food, water and a torch, and to keep it where it is easy to (5)____. Make sure that everyone knows how to (6)____ off the water, the gas and the electricity. Younger children should (7)____ their parents'' phone numbers by heart. Practise the plan two or three (8)____ a year, just like a school fire drill. A good plan will not stop a disaster from (9)____, but it can keep your family much (10)____ when one does.', 133, 2, '[{"q":"1","answer":"A","options":["plan","game","song","price"],"explanation":"have a plan 制定计划。"},{"q":"2","answer":"B","options":["noise","spot","price","song"],"explanation":"a safe spot 安全的地点。"},{"q":"3","answer":"C","options":["toy","meal","way","song"],"explanation":"the quickest way out 最快的出路。"},{"q":"4","answer":"D","options":["sell","throw","hide","prepare"],"explanation":"prepare a kit 准备一个工具包。"},{"q":"5","answer":"A","options":["reach","sell","break","spend"],"explanation":"easy to reach 容易拿到。"},{"q":"6","answer":"B","options":["sing","turn","buy","grow"],"explanation":"turn off 关掉。"},{"q":"7","answer":"C","options":["sell","drop","learn","spill"],"explanation":"learn ... by heart 记牢。"},{"q":"8","answer":"D","options":["metres","songs","prices","times"],"explanation":"two or three times a year 一年两三次。"},{"q":"9","answer":"A","options":["happening","singing","shopping","cooking"],"explanation":"stop ... from happening 阻止其发生。"},{"q":"10","answer":"B","options":["richer","safer","louder","colder"],"explanation":"much safer 安全得多。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'The Morning the Earth Shook', 'I was still asleep when a deep (1)____ woke me before dawn. My bed was shaking so hard that I could not (2)____ up. I heard glass (3)____ as the windows broke one by one. Dust got into my (4)____, and I could not even shout for help. Just then my brother grabbed my arm and (5)____ me towards the door. We reached the street only seconds before the bricks came (6)____ down behind us. When the ground finally became (7)____ again, the silence felt strange and frightening. Around me, weak houses had (8)____ down, and people stood crying in the street. For a long time I was too (9)____ to move at all. Later, I felt thankful that my family was still (10)____ after such a terrible night.', 129, 2, '[{"q":"1","answer":"C","options":["song","price","roar","smell"],"explanation":"a deep roar 低沉的轰鸣。"},{"q":"2","answer":"D","options":["sell","sing","buy","stand"],"explanation":"could not stand up 站不起来。"},{"q":"3","answer":"A","options":["breaking","singing","growing","cooking"],"explanation":"hear glass breaking 听见玻璃破碎。"},{"q":"4","answer":"B","options":["pocket","throat","garden","market"],"explanation":"dust got into my throat 灰尘进了喉咙。"},{"q":"5","answer":"C","options":["sold","sang","pulled","bought"],"explanation":"pulled me towards the door 把我拉向门口。"},{"q":"6","answer":"D","options":["singing","cooking","shopping","pouring"],"explanation":"came pouring down 倾泻而下。"},{"q":"7","answer":"A","options":["still","rich","loud","sweet"],"explanation":"became still 重归平静。"},{"q":"8","answer":"B","options":["grown","fallen","sold","sung"],"explanation":"had fallen down 倒塌了。"},{"q":"9","answer":"C","options":["happy","proud","frightened","hungry"],"explanation":"too frightened to move 吓得不敢动。"},{"q":"10","answer":"D","options":["rich","busy","late","alive"],"explanation":"still alive 还活着。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'The Little Radio That Saves Lives', 'During a big storm, the electricity often goes out, and the television and the internet stop (1)____. That is why a battery-powered weather (2)____ is one of the most useful things you can own. Through it you can hear the latest (3)____ about the storm. You will learn when it is time to (4)____ your home and move to higher ground. You will also hear (5)____ on how to stay safe inside your shelter. Because it runs on (6)____, the radio keeps working even when the power is (7)____. Always keep some (8)____ batteries beside it, so it will never go silent at the worst (9)____. A radio is cheap and small, but in an emergency it can be the one thing that keeps you (10)____ to the outside world.', 130, 2, '[{"q":"1","answer":"A","options":["working","singing","eating","sleeping"],"explanation":"stop working 停止工作。"},{"q":"2","answer":"B","options":["garden","radio","market","price"],"explanation":"a weather radio 气象收音机。"},{"q":"3","answer":"C","options":["songs","prices","news","meals"],"explanation":"the latest news 最新消息。"},{"q":"4","answer":"D","options":["sell","grow","sing","leave"],"explanation":"leave your home 离开家。"},{"q":"5","answer":"A","options":["advice","noise","weather","price"],"explanation":"hear advice 听到建议。"},{"q":"6","answer":"B","options":["water","batteries","wind","paper"],"explanation":"runs on batteries 靠电池工作。"},{"q":"7","answer":"C","options":["rich","sweet","off","loud"],"explanation":"the power is off 停电。"},{"q":"8","answer":"D","options":["sweet","loud","rich","spare"],"explanation":"spare batteries 备用电池。"},{"q":"9","answer":"A","options":["moment","garden","market","price"],"explanation":"at the worst moment 在最糟的时刻。"},{"q":"10","answer":"B","options":["hungry","connected","bored","late"],"explanation":"keep you connected 让你保持联系。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'Making Your Home Safer', 'You cannot stop an earthquake, but you can make your home much (1)____ before one comes. Walk through every room and look for tall objects that could (2)____ over and hurt someone. Heavy bookcases and cabinets should be fixed firmly to the (3)____. Store heavy or sharp things on (4)____ shelves, not high up where they might fall on your head. Keep dangerous items, such as glass and (5)____ liquids, in low, locked cupboards. Learn where the safe (6)____ in each room are, for example under a strong table. It is also wise to (7)____ a first-aid class, so that you can help if someone is (8)____. Finally, check that everyone in the family knows how to (9)____ off the gas. A few simple steps today can (10)____ lives tomorrow.', 130, 2, '[{"q":"1","answer":"C","options":["richer","louder","safer","sweeter"],"explanation":"much safer 安全得多。"},{"q":"2","answer":"D","options":["sing","grow","sell","fall"],"explanation":"fall over 倒下。"},{"q":"3","answer":"A","options":["wall","song","price","market"],"explanation":"fixed to the wall 固定在墙上。"},{"q":"4","answer":"B","options":["louder","lower","sweeter","richer"],"explanation":"lower shelves 较低的架子。"},{"q":"5","answer":"C","options":["happy","sweet","harmful","quiet"],"explanation":"harmful liquids 有害液体。"},{"q":"6","answer":"D","options":["songs","prices","markets","spots"],"explanation":"safe spots 安全地点。"},{"q":"7","answer":"A","options":["take","sell","grow","sing"],"explanation":"take a class 上一门课。"},{"q":"8","answer":"B","options":["rich","hurt","glad","late"],"explanation":"someone is hurt 有人受伤。"},{"q":"9","answer":"C","options":["sing","grow","turn","buy"],"explanation":"turn off 关掉。"},{"q":"10","answer":"D","options":["sell","sing","spill","save"],"explanation":"save lives 拯救生命。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'Rescued from the Flood', 'The rain had fallen for three days when the river finally (1)____ its banks. Within an hour, the streets of the small town had turned into (2)____. The Li family climbed to the top (3)____ of their house and waited there. Mr Li used his phone, which still had (4)____ batteries, to call for help. Outside, the brown water kept (5)____, carrying away cars and furniture. The family felt afraid, but they tried hard to stay (6)____. At last they heard the sound of a (7)____ coming closer through the rain. A rescue team had come in a small one to (8)____ them. One by one, they were helped aboard and taken to (9)____ ground. That night, safe in a shelter, the children said they would never (10)____ the day the water came.', 133, 2, '[{"q":"1","answer":"A","options":["broke","sold","sang","grew"],"explanation":"broke its banks 决堤。"},{"q":"2","answer":"B","options":["gardens","rivers","markets","songs"],"explanation":"turned into rivers 变成了河流。"},{"q":"3","answer":"C","options":["song","price","floor","market"],"explanation":"the top floor 顶层。"},{"q":"4","answer":"D","options":["sweet","loud","rich","extra"],"explanation":"extra batteries 额外的电池。"},{"q":"5","answer":"A","options":["rising","singing","smiling","sleeping"],"explanation":"kept rising 不断上涨。"},{"q":"6","answer":"B","options":["angry","calm","proud","hungry"],"explanation":"stay calm 保持冷静。"},{"q":"7","answer":"C","options":["song","price","boat","garden"],"explanation":"the sound of a boat 一条船的声音。"},{"q":"8","answer":"D","options":["sell","sing","grow","save"],"explanation":"come to save them 来救他们。"},{"q":"9","answer":"A","options":["higher","louder","sweeter","richer"],"explanation":"higher ground 更高的地方。"},{"q":"10","answer":"B","options":["sell","forget","sing","grow"],"explanation":"never forget 永远不会忘记。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'Why People Panic', 'Experts say that the main (1)____ people panic during a disaster is that they do not know what to do. When the ground shakes or the water (2)____, a frightened mind often makes poor choices. The best way to fight this fear is to be (3)____ in advance. If you have already made a plan and (4)____ it a few times, your body will know how to act. Try to take a deep (5)____ and think before you move. Help the people around you to stay (6)____ too, because fear spreads quickly in a crowd. Never (7)____ towards a lift during an earthquake; always use the stairs. If you are driving, slow down and come to a gentle (8)____. Remember that most disasters (9)____ only a short time. Staying calm will not make the danger smaller, but it will help you make (10)____ choices.', 144, 2, '[{"q":"1","answer":"C","options":["price","garden","reason","song"],"explanation":"the main reason 主要原因。"},{"q":"2","answer":"D","options":["sings","grows","sells","rises"],"explanation":"the water rises 水位上涨。"},{"q":"3","answer":"A","options":["ready","rich","loud","sweet"],"explanation":"be ready in advance 事先准备好。"},{"q":"4","answer":"B","options":["sold","practised","sang","grew"],"explanation":"practised it a few times 练过几次。"},{"q":"5","answer":"C","options":["price","garden","breath","song"],"explanation":"take a deep breath 深吸一口气。"},{"q":"6","answer":"D","options":["angry","hungry","proud","calm"],"explanation":"stay calm 保持冷静。"},{"q":"7","answer":"A","options":["run","sing","grow","sell"],"explanation":"never run towards a lift 切勿冲向电梯。"},{"q":"8","answer":"B","options":["song","stop","price","garden"],"explanation":"come to a gentle stop 缓缓停下。"},{"q":"9","answer":"C","options":["sell","sing","last","grow"],"explanation":"last only a short time 只持续很短时间。"},{"q":"10","answer":"D","options":["louder","sweeter","richer","better"],"explanation":"make better choices 做出更好的选择。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 Getting Ready for a Typhoon', '上外版选择性必修第二册 U4 · dialogue', 3, 'Mum: A strong typhoon is coming tonight, so we need to get ready.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 What to Do in an Earthquake', '上外版选择性必修第二册 U4 · passage', 2, 'If an earthquake strikes while you are indoors, do not run outside at once.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 Building a Survival Kit', '上外版选择性必修第二册 U4 · dialogue', 3, 'Lily: Our teacher asked us to make a survival kit at home. Where do we start?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 Floods', '上外版选择性必修第二册 U4 · passage', 2, 'Floods are one of the most common natural disasters in the world.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 After the Storm', '上外版选择性必修第二册 U4 · dialogue', 3, 'Reporter: Excuse me, can you tell me what happened here last night?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 Wildfire Safety', '上外版选择性必修第二册 U4 · passage', 2, 'Wildfires can spread very quickly and destroy everything in their path.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write an expository essay about a natural disaster(写一篇介绍某种自然灾害的说明文)', 'Earthquakes: What They Are and How to Stay Safe', '假设你校举办''防灾教育周'',要求每班写一篇英语说明文,向同学介绍一种自然灾害,以提高大家的防灾意识。请用英语写一篇约100–120词的说明文,内容包括:① 简要说明这种灾害是什么(下定义);② 它的危害;③ 它的主要成因;④ 人们可以采取的应对措施。注意:语言客观、信息清晰,不掺入个人感受。', 'Your school is holding a Disaster Education Week. Each class must write an expository essay (about 100-120 words) introducing one natural disaster, in order to raise students'' awareness. Your essay should include: 1) a short definition of the disaster; 2) its harmful effects; 3) its main causes; 4) measures people can take. Keep the writing objective, informative and clear.', '["下定义(An earthquake is a sudden shaking of the ground caused by …)","危害(It may knock down houses, break roads and put lives in danger.)","成因(Most earthquakes happen where the Earth''s plates suddenly slip.)","应对措施(Fix heavy furniture, keep a survival kit, and know where to hide.)"]'::jsonb, 70, 100, 'An earthquake is a sudden, violent shaking of the ground caused by the movement of rocks deep under the Earth''s surface. It can be one of the most destructive natural disasters of all. When a strong earthquake strikes, it may knock down houses, break roads and pipes, and put many lives in danger. Most earthquakes happen near the edges of the Earth''s great plates, where the rocks suddenly slip. Although we cannot stop earthquakes, we can prepare for them. Fixing heavy furniture to the wall, keeping a survival kit ready, and knowing where to hide can all save lives. By staying calm and acting quickly, people have a much better chance of surviving.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["An earthquake is a sudden, violent shaking of the ground caused by the movement of rocks deep underground.","When a strong earthquake strikes, it may knock down houses, break roads and put many lives in danger.","Although we cannot stop earthquakes, we can prepare for them.","By staying calm and acting quickly, people have a much better chance of surviving."]'::jsonb, '[{"wrong":"An earthquake is caused by the move of rocks.","correct":"An earthquake is caused by the movement of rocks.","note":"此处指''运动、移动''用名词 movement,move 多作动词。"},{"wrong":"It may put many lives in danger after it strikes suddenly.","correct":"When it strikes, it may put many lives in danger.","note":"说明文宜先交代条件再说结果,语序更清晰客观。"},{"wrong":"We can prepare them by fixing furniture.","correct":"We can prepare for them by fixing furniture.","note":"prepare for sth 表''为某事做准备'',不可漏 for。"}]'::jsonb, '【自然灾害说明文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective2', 'U4', '{"title":"复合动名词 complex -ing 速查(被动 being done · 完成 having done)","intro":"动名词除了简单形式 doing,还有被动式、完成式、否定式,并可带自己的逻辑主语。判断口诀:看逻辑主语是主动还是被动→选 doing / being done;看动作是否早于主句完成→选 doing / having done;否定就在前面加 not。","table":{"headers":["形式","用法 / 例句"],"rows":[["being done(被动)","逻辑主语是动作承受者:afraid of being buried 害怕被埋"],["having done(完成)","动作主动且早于主句:proud of having saved ten people 为救了十人而自豪"],["having been done(完成被动)","被动且早于主句:after having been rescued 在被救出之后"],["not doing(否定)","在 -ing 前加 not:not knowing what to do 不知所措"],["sb(''s) doing(带逻辑主语)","动名词前带自己的主语:no point in us staying 我们留下没意义"]]},"specialRules":[{"rule":"承受者用被动:介词后若逻辑主语''被…'',用 being done","mark":"in danger of being washed away(桥被冲走)"},{"rule":"在先的动作用完成式:有明显时间先后时用 having done","mark":"praised for having saved all the passengers(先救人后受表扬)"},{"rule":"否定加 not,且 not 放在最前","mark":"Not following the order, … √ / Following not … ×"},{"rule":"不及物动词(arrive/escape/rise/shout)无被动式,不能用 being done","mark":"depend on the helicopter arriving √ / being arrived ×"}],"why":["动名词本质是''名词化的动作'';当这个动作的承受者做逻辑主语时就要被动(being done),当它发生在主句之前就要完成(having done)。两者可叠加成 having been done。"],"gaokaoPoints":["介词(of/for/without/after/about)+ 动名词:辨被动 being done 还是主动 doing。","完成式 having done 与简单式 doing 的时间先后判断;否定式 not doing 作状语表原因。","动名词的复合结构(sb(''s) doing)及''不及物动词无被动''这一易错点,常出现在语法填空与改错。"],"examVsReal":[{"exam":"He was proud of having saved ten people.（书面/考试）","real":"He was proud he had saved ten people. / proud of saving ten people","note":"口语里常用从句或简单动名词;时间先后清楚时,简单式 saving 也很常见"},{"exam":"Not knowing what to do, they panicked.（书面）","real":"They didn''t know what to do, so they panicked.","note":"考试爱用 -ing 状语;口语更常拆成两个并列/因果分句"}]}'::jsonb, 'sufe');
